def doc_batch(*, out_dir: str, paths: list, steps: list, dpi: float = None, language: str = None, ppi: float = None, quality: int = None, recursive: bool = None, skip_text_pages: bool = None, stop_on_error: bool = None) -> Result:
    """Process files and folders  [doc_batch]
    
    Run convert, ocr and/or optimize over files and folders, one file at a time. recursive defaults
    to false. Preserve paths relative to each selected folder inside out_dir; duplicate inputs run
    once. Skip unsupported files, links and the output subtree. Existing outputs receive numbered
    names and are never replaced. Continue after per-file errors unless stop_on_error is true.
    Return completed/failed/skipped counts and per-file results. Discovery is bounded to 10000
    entries and 64 folder levels. Convert must be first; each step can appear once. OCR uses
    installed models. Optimize uses Reduce File Size settings, optionally overriding target ppi
    (threshold 1.5 times ppi; black-and-white images go to the larger of ppi and 300) and JPEG
    quality; a larger candidate keeps the original bytes. Sources and open documents are unchanged.
    
    Args:
        out_dir (str):
        paths (list):
        steps (list):
        dpi (float, optional):
        language (str, optional):
        ppi (float, optional):
        quality (int, optional):
        recursive (bool, optional):
        skip_text_pages (bool, optional):
        stop_on_error (bool, optional):
    """
    return run_tool('doc_batch', **{k: v for k, v in {'out_dir': out_dir, 'paths': paths, 'steps': steps, 'dpi': dpi, 'language': language, 'ppi': ppi, 'quality': quality, 'recursive': recursive, 'skip_text_pages': skip_text_pages, 'stop_on_error': stop_on_error}.items() if v is not None})

def doc_bates_multi(*, files: list, digits: int = None, dry_run: bool = None, prefix: str = None, start_number: int = None, suffix: str = None) -> Result:
    """Add Bates numbering across files  [doc_bates_multi]
    
    Apply one consecutive Bates sequence to an ordered list of PDFs. Each file entry has input and
    output paths and an optional open or permissions password. The operation first validates every
    input/output and computes inclusive numeric intervals; dry_run returns that allocation without
    writing. Existing output files are never replaced. On application, files that cannot be edited
    or saved are reported individually and later files continue.
    
    Args:
        files (list): PDFs in Bates sequence order.
        digits (int, optional): Zero-padded number width (default 6).
        dry_run (bool, optional): Return each file's inclusive number interval without writing
            (default false).
        prefix (str, optional): Text before the number: at most 128 UTF-8 bytes, without # or >>.
        start_number (int, optional): First number in the sequence (default 1).
        suffix (str, optional): Text after the number: at most 128 UTF-8 bytes, without # or >>.
    """
    return run_tool('doc_bates_multi', **{k: v for k, v in {'files': files, 'digits': digits, 'dry_run': dry_run, 'prefix': prefix, 'start_number': start_number, 'suffix': suffix}.items() if v is not None})

def doc_combine(*, paths: list, field_conflicts: Literal['rename', 'merge'] = None, groups: list = None, open: bool = None, out: str = None, pages: list = None, passwords: list = None) -> Result:
    """Combine files  [doc_combine]
    
    Combine files, in order, into one PDF (bookmarks are kept under one entry per file). Images
    (PNG, JPEG, TIFF, GIF, BMP, JPEG 2000), .txt files and Word/Excel/PowerPoint/RTF documents
    (.docx, .xlsx, .pptx, .rtf) are made into PDFs first. pages optionally chooses each file's
    pages, in step with paths: a range such as "1-3, 6" or null for all pages. passwords, also in
    step with paths, opens encrypted files (the open password, or the permissions password where a
    file's security doesn't allow copying pages; null for none). The result is not encrypted.
    Passwords are never echoed back. groups, also in step with paths, splits a file around others:
    entries with the same number (they must name the same path) are one file, copied once, so it
    keeps one bookmark at its first page, its links and its form fields; null for a file of its own.
    A group uses its first entry's password. When two files' forms name the same field,
    field_conflicts says what happens: "rename" (the default) keeps the fields separate by renaming
    the later one (Text1 becomes Text1-1) and the result lists renamed_fields as [[old, new], …] —
    scripts that refer to the old name are not rewritten; "merge" makes them one field, as before.
    
    Args:
        paths (list):
        field_conflicts (Literal['rename', 'merge'], optional):
        groups (list, optional):
        open (bool, optional): Also open the result as a new document (default: only when out is
            omitted).
        out (str, optional): File to write. Omit to open the result as a new unsaved document
            instead.
        pages (list, optional):
        passwords (list, optional):
    """
    return run_tool('doc_combine', **{k: v for k, v in {'paths': paths, 'field_conflicts': field_conflicts, 'groups': groups, 'open': open, 'out': out, 'pages': pages, 'passwords': passwords}.items() if v is not None})

