def doc_export_office(src, *, path: str, html_mode: Literal['rich', 'simple'] = None, out=None, inplace=False, password=None) -> Result:
    """Export to Word, Excel, PowerPoint, HTML, RTF or Markdown  [doc_export_office]
    
    Export a PDF ▸ Word (.docx), Excel (.xlsx), PowerPoint (.pptx), HTML (.html, one file with
    images inline), RTF (.rtf) or Markdown (.md or .markdown: pipe tables, images left out), chosen
    by path's extension: text, headings, bold and italic. HTML uses rich styling by default; set
    html_mode to simple for CSS-free headings, paragraphs, emphasis and tables. Simple HTML keeps
    text and inline images but omits colour and layout styling. Word uses borderless inferred tables
    and positioned editable shapes on pages with artwork, rotated or large text; each source page
    retains its size. Excel writes one worksheet per page: detected tables as cell grids (spanning
    cells merged, plain numbers as numbers), other paragraphs one per row in column A; images are
    left out. PowerPoint writes one slide per page (sized like the first page) with each paragraph
    as a text box, each image as a picture and each detected table as a table, at their page
    positions. Font matching and vector graphics remain limited. Export reads forms 50 deep and up
    to 50 000 a page, counting forms the page draws itself. Pages that go past either limit, or that
    have pictures past what one export may hold or decode, are listed in truncated_pages, with a
    warning; what was left out is missing.
    
    Args:
        path (str):
        html_mode (Literal['rich', 'simple'], optional):
    """
    return apply(src, 'doc_export_office', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'path': path, 'html_mode': html_mode}.items() if v is not None})

