def doc_optimize(src, *, path: str, color: dict = None, compatibility: Literal['retain', '1.4', '1.5', '1.6', '1.7', '2.0'] = None, discard: list = None, discard_alternate_images: bool = None, discard_print_settings: bool = None, discard_tags: bool = None, discard_thumbnails: bool = None, flate_unencoded: bool = None, gray: dict = None, lzw_to_flate: bool = None, merge_fragments: bool = None, mono: dict = None, object_streams: bool = None, preset: Literal['standard', 'mobile'] = None, remove_invalid_links: bool = None, remove_unreferenced_dests: bool = None, out=None, inplace=False, password=None) -> Result:
    """Optimize PDF  [doc_optimize]
    
    Write an optimized copy to `path` (Acrobat's PDF Optimizer). preset: standard (default; Reduce
    File Size's choices) or mobile (images to 96 ppi above 144, JPEG high quality); the options
    below change it. compatibility: retain (default; keeps the document's version, or 1.5 when
    object streams are written), 1.4, 1.5, 1.6, 1.7 or 2.0. merge_fragments (default true) first
    puts a page picture drawn as many stacked image strips (as some PDF printers write it) back
    together into one image, so it can be resampled (merged_images, fragments_merged). color / gray:
    { downsample, ppi, above_ppi, compression: jpeg|zip|retain, quality 1–100 } (defaults:
    downsample to 150 ppi above 225, JPEG 60). mono: { downsample, ppi, above_ppi, compression:
    ccitt_g4|jbig2|retain } for black-and-white images and image masks (default: averaged down to
    300 ppi above 450 ppi, counted in images_resampled; stored losslessly as CCITT Group 4 or JBIG2
    (or 1-bit Flate, once resampled or packed from more bits) when that is smaller, Group 3 fax
    images, JBIG2 images, black-and-white RGB and indexed images using only palette entries 0 and 1
    among them, counted in images_recompressed; retain resamples only, a CCITT image staying CCITT,
    a JBIG2 image JBIG2 and any other becoming Flate). Images past what one run may decode stay as
    they are, counted in images_refused; streams it only stores with Flate past that stay LZW,
    uncounted. Images are measured where pages draw them and replaced only when smaller. discard_*:
    thumbnails (default true), alternate_images (true), tags, print_settings; flate_unencoded
    (true); object_streams (default true; always off for 1.4); lzw_to_flate (true) decodes LZW
    streams and stores them with Flate instead, leaving any it cannot decode unchanged (lzw_streams
    counts the streams converted); remove_invalid_links and remove_unreferenced_dests (true); images
    and forms the pages list but never draw are always dropped (unused_xobjects). discard: Remove
    Hidden Information categories (metadata, attachments, comments, form-fields, hidden-text,
    hidden-layers, bookmarks, links-actions-scripts, private-data). Signed documents are refused.
    The open document is unchanged.
    
    Args:
        path (str):
        color (dict, optional):
        compatibility (Literal['retain', '1.4', '1.5', '1.6', '1.7', '2.0'], optional):
        discard (list, optional):
        discard_alternate_images (bool, optional):
        discard_print_settings (bool, optional):
        discard_tags (bool, optional):
        discard_thumbnails (bool, optional):
        flate_unencoded (bool, optional):
        gray (dict, optional):
        lzw_to_flate (bool, optional):
        merge_fragments (bool, optional):
        mono (dict, optional):
        object_streams (bool, optional):
        preset (Literal['standard', 'mobile'], optional):
        remove_invalid_links (bool, optional):
        remove_unreferenced_dests (bool, optional):
    """
    return apply(src, 'doc_optimize', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'path': path, 'color': color, 'compatibility': compatibility, 'discard': discard, 'discard_alternate_images': discard_alternate_images, 'discard_print_settings': discard_print_settings, 'discard_tags': discard_tags, 'discard_thumbnails': discard_thumbnails, 'flate_unencoded': flate_unencoded, 'gray': gray, 'lzw_to_flate': lzw_to_flate, 'merge_fragments': merge_fragments, 'mono': mono, 'object_streams': object_streams, 'preset': preset, 'remove_invalid_links': remove_invalid_links, 'remove_unreferenced_dests': remove_unreferenced_dests}.items() if v is not None})

