def doc_protect(src, *, accessibility: bool = None, changes: Literal['none', 'pages', 'fill-sign', 'comment-fill-sign', 'any-except-extract'] = None, compatibility: Literal['aes-256', 'aes-128', 'rc4-128', 'rc4-40'] = None, copy: bool = None, encrypt_metadata: bool = None, open_password: str = None, permissions_password: str = None, printing: Literal['none', 'low', 'high'] = None, out=None, inplace=False, password=None) -> Result:
    """Protect with passwords  [doc_protect]
    
    Encrypt the document (applied by the next doc_save, a full rewrite). open_password is needed to
    open it. permissions_password is needed to change security and lifts the restrictions given by
    printing/changes/copy/accessibility; those restrictions (and their defaults) apply only when
    permissions_password is given. With open_password alone the document is encrypted and everything
    stays allowed, so passing a restriction without permissions_password is an error. Passwords are
    never echoed back. Undoable.
    
    Args:
        accessibility (bool, optional): Allow screen readers to read the text (needs
            permissions_password; default true).
        changes (Literal['none', 'pages', 'fill-sign', 'comment-fill-sign', 'any-except-extract'],
            optional): Needs permissions_password. Default none.
        compatibility (Literal['aes-256', 'aes-128', 'rc4-128', 'rc4-40'], optional): Default
            aes-256 (Acrobat X and later).
        copy (bool, optional): Allow copying text and images (needs permissions_password; default
            false).
        encrypt_metadata (bool, optional): Default true.
        open_password (str, optional): Required to open the document. On its own it restricts
            nothing.
        permissions_password (str, optional): Required to change security; enables
            printing/changes/copy/accessibility and their defaults.
        printing (Literal['none', 'low', 'high'], optional): Needs permissions_password. Default
            high.
    """
    return apply(src, 'doc_protect', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'accessibility': accessibility, 'changes': changes, 'compatibility': compatibility, 'copy': copy, 'encrypt_metadata': encrypt_metadata, 'open_password': open_password, 'permissions_password': permissions_password, 'printing': printing}.items() if v is not None})

