def form_calculation_order(src, *, field: str = None, fix: bool = None, move: Literal['earlier', 'later'] = None, order: list = None, out=None, inplace=False, password=None) -> Result:
    """Read or set the calculation order  [form_calculation_order]
    
    The calculated fields in the order they calculate (Acrobat: Set Field Calculation Order), each
    with its `formula` (as form_fields shows calculate), the fields it reads (`reads`; a script's
    names built at run time aren't known) and its `issues`: missing_field (it reads `field`, which
    the form doesn't have, so it gets no value there), runs_too_early (it reads `field`, which
    calculates after it, so it shows a stale value), cycle (it reads `fields`, which read it back:
    no order fixes that, a formula has to change) and not_in_order (the PDF's order leaves it out,
    so other viewers may not calculate it) and built_names (its script also reads fields by names it
    builds at run time, which aren't checked). `extra` lists entries of the PDF's order that
    calculate nothing. Without a change it only reads. Changes, one at a time: `order` (these fields
    first, in this order, then the other calculated fields in their order), `field` with `move`
    earlier|later (one place), or `fix` true (only what must move moves, so every field calculates
    after the fields it reads, and the extra entries go). A change recalculates the form. Undoable.
    
    Args:
        field (str, optional):
        fix (bool, optional):
        move (Literal['earlier', 'later'], optional):
        order (list, optional):
    """
    return apply(src, 'form_calculation_order', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'field': field, 'fix': fix, 'move': move, 'order': order}.items() if v is not None})

