def form_set_props(src, *, align: Literal['left', 'center', 'right'] = None, appearance: dict = None, calculate: Any = None, caption: str = None, check_style: Literal['check', 'circle', 'cross', 'diamond', 'square', 'star'] = None, default: str = None, export_value: str = None, field: str = None, fields: list = None, flags: dict = None, font_size: float = None, format: Any = None, locked: bool = None, max_length: int = None, multiline: bool = None, name: str = None, options: list = None, read_only: bool = None, rect: list = None, required: bool = None, rotation: Literal[0, 90, 180, 270] = None, tooltip: str = None, validate: Any = None, widget: int = None, out=None, inplace=False, password=None) -> Result:
    """Field properties  [form_set_props]
    
    Change field properties: give field for one field, or fields for a list of unique field names
    (1–1000). A bulk change is atomic and one Undo step; an invalid or locked field leaves every
    field unchanged. Only the given properties change, and partial appearance changes preserve each
    field's other colours and font. name (rename: a dotted name such as MASTER.first is the full
    name and moves the field under those parent fields; a plain name renames it within its parent),
    rect (position), rotation and caption require a single field. A rename also renames the field in
    the calculations that read it (calculate field lists and notation, and getField calls naming it
    in a string literal; names built at run time are not rewritten), in the same Undo step, and
    formulas_updated lists the fields whose calculation changed. caption changes one push-button
    normal label (widget: 1-based index, default 1); an empty string clears it. Other widgets and
    icon-only layouts are preserved. General and Options: tooltip, read_only, required, multiline,
    max_length (0 = no limit), options (combo/list items), font_size (0 = auto), format, validate,
    calculate (Acrobat's native AF rules). Options: align (left, center, right), default (Reset
    form's value; check boxes/radio buttons use their on state, "" for off), flags { scroll,
    rich_text, password, file_select, spell_check, comb (needs max_length), sort, editable,
    multi_select, commit_immediately }, check_style (check boxes/radio buttons: check, circle,
    cross, diamond, square, star). rotation is 0, 90, 180 or 270 degrees counterclockwise and swaps
    width/height when the axis changes. Undoable.
    
    Args:
        align (Literal['left', 'center', 'right'], optional):
        appearance (dict, optional): Appearance tab: border, fill, text_color (#RRGGBB, a name or
            "none"), width (0–12 points; 1 thin, 2 medium, 3 thick), style (solid, dashed, beveled,
            inset, underline), font (helvetica, times, courier).
        calculate (Any, optional): Calculate tab: {"op": "sum"|"product"|"average"|"min"|"max",
            "fields": ["a", "b"]}, {"notation": "Price * Qty"} (simplified field notation), or
            "none".
        caption (str, optional): Normal push-button label; an empty string clears it. Requires a
            single field.
        check_style (Literal['check', 'circle', 'cross', 'diamond', 'square', 'star'], optional):
            Check boxes and radio buttons: the mark shown when on.
        default (str, optional):
        export_value (str, optional): Checkbox/radio export value; preserves appearance states and
            selection. Requires a single field.
        field (str, optional): The field's current name.
        fields (list, optional): Apply the same changes to these fields in one atomic edit. Use
            either field or fields.
        flags (dict, optional):
        font_size (float, optional):
        format (Any, optional): Format tab: {"type": "number", "decimals": 2, "currency": "$",
            "separator": 0-4, "negative": 0-3}, {"type": "percent"}, {"type": "date"|"time",
            "pattern": "mm/dd/yyyy"}, {"type": "zip"|"zip4"|"phone"|"ssn"}, {"type": "mask", "mask":
            "AA-9999"}, or "none".
        locked (bool, optional): Lock the field's properties (only unlocking is accepted while
            locked).
        max_length (int, optional):
        multiline (bool, optional):
        name (str, optional):
        options (list, optional):
        read_only (bool, optional):
        rect (list, optional): Move/resize: points from the top-left of the displayed page.
        required (bool, optional):
        rotation (Literal[0, 90, 180, 270], optional): Widget rotation in degrees, counterclockwise.
            Changing between horizontal and vertical swaps the rectangle around its center.
        tooltip (str, optional):
        validate (Any, optional): Validate tab: {"min": 0, "max": 100} (either may be left out, or
            null) or "none".
        widget (int, optional): Widget whose caption or export value changes (1-based, default 1).
            Requires caption or export_value. See form_fields.captions and export_values.
    """
    return apply(src, 'form_set_props', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'align': align, 'appearance': appearance, 'calculate': calculate, 'caption': caption, 'check_style': check_style, 'default': default, 'export_value': export_value, 'field': field, 'fields': fields, 'flags': flags, 'font_size': font_size, 'format': format, 'locked': locked, 'max_length': max_length, 'multiline': multiline, 'name': name, 'options': options, 'read_only': read_only, 'rect': rect, 'required': required, 'rotation': rotation, 'tooltip': tooltip, 'validate': validate, 'widget': widget}.items() if v is not None})

