def image_edit(src, *, action: Literal['move', 'crop', 'rotate', 'rotate_by', 'transform', 'flip_horizontal', 'flip_vertical', 'replace', 'delete', 'bring_to_front', 'send_to_back', 'bring_forward', 'send_backward', 'remove_crop'], image: int, page: int, degrees: float = None, matrix: list = None, path: str = None, quarters: int = None, rect: list = None, out=None, inplace=False, password=None) -> Result:
    """Edit an image  [image_edit]
    
    Change one of a page's images (number from page_images): action move (rect: new full placement
    box in top-left-origin points, based on page_images.rect), crop (rect: the part to keep, top-
    left-origin points; the pixels stay in place and page_images.visible_rect shows the result; a
    later move carries the crop along), remove_crop (remove a crop created by PdfCraft while
    preserving clipping paths from the original document), rotate (quarters clockwise, default 1),
    rotate_by (degrees: any angle clockwise about the visible centre; the box in page_images then
    becomes the turned image's bounding box), transform (matrix: 6 numbers [a, b, c, d, e, f] in
    top-left-origin points, applied after the current placement so a point (x, y) of the image moves
    to (a·x + c·y + e, b·x + d·y + f); finite, with a·d − b·c not 0; the box in page_images becomes
    the transformed image's bounding box), flip_horizontal (reflect left/right on the displayed
    page), flip_vertical (reflect top/bottom on the displayed page; both flip actions follow the
    page rotation), replace (path: an image file, drawn in the same place), delete, or arrange:
    bring_to_front, send_to_back, bring_forward, send_backward (reorder stacking order among content
    on the page; errors when the image is already at the requested limit; arranging an added image
    converts it into an ordinary page image). Undoable. The selected image crop transforms with its
    pixels, isolating shared path scopes while retaining neighboring painting. Text-outline clips
    return a clear error. Rotation/flip use the visible centre. Form artwork supports
    move/resize/rotate/flip/delete as a group; replace and image_save only support raster images.
    
    Args:
        action (Literal['move', 'crop', 'rotate', 'rotate_by', 'transform', 'flip_horizontal',
            'flip_vertical', 'replace', 'delete', 'bring_to_front', 'send_to_back', 'bring_forward',
            'send_backward', 'remove_crop']):
        image (int):
        page (int):
        degrees (float, optional):
        matrix (list, optional):
        path (str, optional):
        quarters (int, optional):
        rect (list, optional):
    """
    return apply(src, 'image_edit', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'action': action, 'image': image, 'page': page, 'degrees': degrees, 'matrix': matrix, 'path': path, 'quarters': quarters, 'rect': rect}.items() if v is not None})

