def page_enhance_camera(src, *, page: int, corners: list = None, level: int = None, mode: Literal['original', 'colour', 'greyscale', 'bw'] = None, out=None, inplace=False, password=None) -> Result:
    """Enhance camera image  [page_enhance_camera]
    
    Straighten a photographed document (Scan & OCR ▸ Enhance ▸ Camera image): the part of the page
    inside the four corners (x1, y1, … x4, y4 in top-left-origin points, any order, a convex
    quadrilateral; when omitted, the document's edges are found automatically, or an error says they
    could not be) is warped to an upright rectangle that replaces what the page shows, at the page
    picture's own resolution (at most 600 dpi). mode is how it looks: original, colour (default),
    greyscale or bw (black and white, stored losslessly). level (0–100, default 0) then cleans the
    photo up: even lighting so the paper turns white (casts, shadows, dark edges), more contrast,
    and from 60 no isolated specks; colour ink stays colour. For bw the level is the threshold
    (higher keeps fainter strokes black). The page's comments, links and bookmarks stay. Undoable.
    
    Args:
        page (int):
        corners (list, optional):
        level (int, optional):
        mode (Literal['original', 'colour', 'greyscale', 'bw'], optional):
    """
    return apply(src, 'page_enhance_camera', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'page': page, 'corners': corners, 'level': level, 'mode': mode}.items() if v is not None})

def page_extract(src, *, pages: list, delete: bool = None, open: bool = None, out: str = None, out_dir: str = None, separate: bool = None, save_as=None, inplace=False, password=None) -> Result:
    """Extract pages  [page_extract]
    
    Copy pages into a new PDF (links, bookmarks, fields and layers that belong to them come along).
    separate: true writes each page as its own file into out_dir; delete: true removes the pages
    from this document afterwards (undoable).
    
    Args:
        pages (list): 1-based page numbers to extract.
        delete (bool, optional):
        open (bool, optional): Also open the result as a new document (default: only when out is
            omitted).
        out (str, optional): File to write. Omit to open the result as a new unsaved document
            instead.
        out_dir (str, optional):
        separate (bool, optional):
    """
    return apply(src, 'page_extract', out=save_as, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'pages': pages, 'delete': delete, 'open': open, 'out': out, 'out_dir': out_dir, 'separate': separate}.items() if v is not None})

