def page_render(src, *, page: int, dpi: float = None, hide_added_text: int = None, hide_text_block: int = None, out=None, inplace=False, password=None) -> Result:
    """Render a page  [page_render]
    
    Render one page to a PNG image (default 96 dpi, at most 600). When the picture is incomplete or
    approximate (content cut at the page's safety budget, a colour painted in a fallback colour), a
    JSON part follows the image: { page, warnings: [sentence, ...] }.
    
    Args:
        page (int):
        dpi (float, optional):
        hide_added_text (int, optional): Render a retyping background without this added text item
            (added index from object_list). Mutually exclusive with hide_text_block. Does not modify
            the document.
        hide_text_block (int, optional): Render an inline editor background without this paragraph
            (number from text_paragraphs, resolved as text_edit does: refused once an edit merged
            that paragraph into a neighbour). Does not modify the document.
    """
    return apply(src, 'page_render', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'page': page, 'dpi': dpi, 'hide_added_text': hide_added_text, 'hide_text_block': hide_text_block}.items() if v is not None})

