def page_transition_set(src, *, dimension: Literal['horizontal', 'vertical'] = None, direction: Any = None, display: float = None, duration: float = None, motion: Literal['inward', 'outward'] = None, opaque: bool = None, pages: list = None, scale: float = None, style: Literal['none', 'Split', 'Blinds', 'Box', 'Wipe', 'Dissolve', 'Glitter', 'R', 'Fly', 'Push', 'Cover', 'Uncover', 'Fade'] = None, out=None, inplace=False, password=None) -> Result:
    """Set page transitions  [page_transition_set]
    
    Set or remove the transition and display time pages play in a full-screen presentation (ISO
    32000-2 §12.4.4; Acrobat's Organize ▸ Page Transitions). style: Split, Blinds, Box, Wipe,
    Dissolve, Glitter, R (replace, no effect), Fly, Push, Cover, Uncover or Fade, or none to remove
    the transition; duration in seconds (default 1); dimension horizontal/vertical (Split, Blinds);
    motion inward/outward (Split, Box, Fly); direction 0, 90, 180, 270, 315 or none (Wipe, Glitter,
    Fly, Cover, Uncover, Push); scale and opaque for Fly. display: seconds the page stays before
    advancing; left out, the page waits for the presenter. doc_info lists the result under
    transitions.
    
    Args:
        dimension (Literal['horizontal', 'vertical'], optional):
        direction (Any, optional): 0, 90, 180, 270, 315 or "none"
        display (float, optional):
        duration (float, optional):
        motion (Literal['inward', 'outward'], optional):
        opaque (bool, optional):
        pages (list, optional): 1-based page numbers to change (default: all).
        scale (float, optional):
        style (Literal['none', 'Split', 'Blinds', 'Box', 'Wipe', 'Dissolve', 'Glitter', 'R', 'Fly',
            'Push', 'Cover', 'Uncover', 'Fade'], optional):
    """
    return apply(src, 'page_transition_set', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'dimension': dimension, 'direction': direction, 'display': display, 'duration': duration, 'motion': motion, 'opaque': opaque, 'pages': pages, 'scale': scale, 'style': style}.items() if v is not None})

def pdfa_convert(src, *, level: Literal['2b', '3b'] = None, out=None, inplace=False, password=None) -> Result:
    """Save as PDF/A  [pdfa_convert]
    
    Standards ▸ Save as PDF/A: fix what can be fixed for PDF/A-2b or 3b (XMP identification and
    metadata, an sRGB output intent, forbidden actions and JavaScript, annotation print flags, image
    interpolation, encryption). Returns what was fixed and what remains (e.g. fonts that aren't
    embedded). Undoable; save the document to keep it.
    
    Args:
        level (Literal['2b', '3b'], optional):
    """
    return apply(src, 'pdfa_convert', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'level': level}.items() if v is not None})

def pdfa_verify(src, *, level: Literal['2b', '3b'] = None, out=None, inplace=False, password=None) -> Result:
    """Verify PDF/A  [pdfa_verify]
    
    Standards ▸ Verify PDF/A compliance: the PDF/A-2b or 3b rules the document breaks (ISO 19005
    clause, message, page, whether Save as PDF/A can fix it), plus what it declares.
    
    Args:
        level (Literal['2b', '3b'], optional): Default 2b.
    """
    return apply(src, 'pdfa_verify', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'level': level}.items() if v is not None})

