def redact_mark(src, *, author: str = None, case_sensitive: bool = None, code_set: Literal['foia', 'privacy-act'] = None, codes: list = None, fill: str = None, find: str = None, overlay: str = None, page: int = None, pages: list = None, pattern: Literal['phone', 'email', 'credit-card', 'ssn', 'date'] = None, rect: list = None, whole_pages: bool = None, whole_words: bool = None, words: list = None, out=None, inplace=False, password=None) -> Result:
    """Mark for redaction  [redact_mark]
    
    Mark content for redaction (nothing is removed until redact_apply). One of: rect [x0, y0, x1,
    y1] (points from the top-left of the displayed page) with page; find (text, every match); words
    (a list of words or phrases, every match of each; the result's matched_words says how many marks
    each made); pattern (phone, email, credit-card, ssn, date: every match, Acrobat's Search &
    Redact patterns); whole_pages: true. find and words accept case_sensitive and whole_words (both
    default false). Select one page with page or multiple with pages (default all); do not pass
    both. rect requires page. overlay: text shown on the box once applied, or code_set (foia: U.S.
    FOIA (b)(1)(A)…(b)(9); privacy-act: U.S. Privacy Act (d)(5), (j)(1)…(k)(7)) with codes, shown as
    "(b)(6), (b)(7)(C)"; fill: box colour (default black). Undoable.
    
    Args:
        author (str, optional):
        case_sensitive (bool, optional): Match letter case for find or words (default false).
        code_set (Literal['foia', 'privacy-act'], optional):
        codes (list, optional): Redaction codes from code_set, e.g. ["(b)(6)"].
        fill (str, optional): #RRGGBB or a colour name.
        find (str, optional):
        overlay (str, optional):
        page (int, optional): Single page to mark; mutually exclusive with pages.
        pages (list, optional): 1-based page numbers to search or mark (default: all); mutually
            exclusive with page, and not valid with rect.
        pattern (Literal['phone', 'email', 'credit-card', 'ssn', 'date'], optional):
        rect (list, optional):
        whole_pages (bool, optional):
        whole_words (bool, optional): Match whole words for find or words (default false).
        words (list, optional):
    """
    return apply(src, 'redact_mark', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'author': author, 'case_sensitive': case_sensitive, 'code_set': code_set, 'codes': codes, 'fill': fill, 'find': find, 'overlay': overlay, 'page': page, 'pages': pages, 'pattern': pattern, 'rect': rect, 'whole_pages': whole_pages, 'whole_words': whole_words, 'words': words}.items() if v is not None})

