def text_find(src, *, query: str, limit: int = None, skip: int = None, start_page: int = None, out=None, inplace=False, password=None) -> Result:
    """Find text  [text_find]
    
    Find a phrase (case-insensitive, whitespace-normalised) and return matches in page order with
    page and line rectangles in points (origin top-left). Reads growing batches, looking one match
    past the limit for a continuation. Failed pages do not discard readable matches: warnings
    contains up to 100 {page, error, error_truncated} entries (errors capped at 1024 UTF-8 bytes),
    warning_count counts failed pages, and warnings_truncated reports a capped list. complete is
    false after a page failure or when more matches exist; next is present only for a match-limit
    continuation.
    
    Args:
        query (str):
        limit (int, optional): Maximum matches (default 500). When another match exists, next holds
            start_page and skip to continue. complete is false for either additional matches or
            failed pages; an exhausted search with warnings has no next.
        skip (int, optional): Matches to pass over on start_page before returning any (default 0).
        start_page (int, optional): Page to start searching from (default 1).
    """
    return apply(src, 'text_find', out=out, inplace=inplace, password=password, suffix='edited', **{k: v for k, v in {'query': query, 'limit': limit, 'skip': skip, 'start_page': start_page}.items() if v is not None})

